def write(path, items, prefix):
    with path.open('w', newline='', encoding='utf-8') as f:
        w=csv.DictWriter(f, fieldnames=['id','text','label','source'])
        w.writeheader()
        for idx,(label,headline) in enumerate(items,1):
            w.writerow({'id':f'{prefix}-{idx:03d}','text':headline,'label':label,'source':'original synthetic example'})

def main():
    for name,items in [('train_demo.csv',TRAIN),('eval_demo.csv',EVAL)]:
        flat=[(label,title) for label,titles in items.items() for title in titles]
        write(ROOT/'data'/name,flat,'SYN-TR' if name.startswith('train') else 'SYN-EV')
        print(f'{name}: {len(flat)} rows')
if __name__=='__main__': main()
